<?php use MediaPitch\Core\Csrf; ?>
<div class="two-col"><section class="panel"><div class="panel-head"><div><h2>Categories</h2><p>Database-driven catalog structure.</p></div></div><table class="data-table"><thead><tr><th>Name</th><th>Parent</th><th>Slug</th><th>Status</th></tr></thead><tbody><?php foreach($categories as $c):?><tr><td><?= e($c['name']) ?></td><td><?= e($c['parent_name'] ?? '—') ?></td><td><code><?= e($c['slug']) ?></code></td><td><?= !empty($c['active'])?'Active':'Inactive' ?></td></tr><?php endforeach;?></tbody></table></section><section class="panel"><h2>Add category</h2><form method="post" action="<?= e(url('admin/categories/save')) ?>" class="stack-form"><?= Csrf::field() ?><label>Name<input name="name" required></label><label>Slug<input name="slug" required></label><label>Parent<select name="parent_id"><option value="">None</option><?php foreach($categoryOptions as $c):?><option value="<?= (int)$c['id'] ?>"><?= e($c['name']) ?></option><?php endforeach;?></select></label><label>Description<textarea name="description" rows="4"></textarea></label><label>SEO title<input name="seo_title"></label><label>Meta description<textarea name="meta_description" rows="3"></textarea></label><label>Sort order<input type="number" name="sort_order" value="0"></label><label class="check"><input type="checkbox" name="active" value="1" checked> Active</label><button class="primary-button">Save category</button></form></section></div>